import 'dart:convert'; import 'dart:io';
class APIServer { HttpServer? _server; Future<void> start(Future<String> Function(String) generate,{int port=8765}) async {_server=await HttpServer.bind(InternetAddress.loopbackIPv4,port);_server!.listen((r) async {r.response.headers.contentType=ContentType.json;final body=await utf8.decoder.bind(r).join();final prompt=(jsonDecode(body) as Map)['prompt']?.toString()??'';r.response.write(jsonEncode({'choices':[{'message':{'content':await generate(prompt)}}]}));await r.response.close();});} Future<void> stop()=>_server?.close(force:true)??Future.value(); }